import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.CNIcw2kk.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1785542157000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><p>comply checks that every file in a project declares its copyright and licence, following the <a href="https://reuse.software/spec/" target="_blank" rel="noreferrer">REUSE Specification</a>. It is a new implementation in Rust rather than a port of the Python <code>reuse</code> tool, and it reads the same configuration.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> comply</span></span></code></pre></div><p>One crate, <code>comply</code>, carrying both the binary and the library. To use it as a library only, depend on it with <code>default-features = false</code>.</p><p>To build from a checkout:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/elioseverojunior/comply</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> comply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/comply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>comply needs <code>git</code> to see which files a repository tracks, and <code>curl</code> for <code>comply download</code>. Nothing else: the SPDX licence list is compiled into the binary, so checking works offline.</p><h2 id="the-shape-of-a-compliant-project" tabindex="-1">The shape of a compliant project <a class="header-anchor" href="#the-shape-of-a-compliant-project" aria-label="Permalink to “The shape of a compliant project”">​</a></h2><p>REUSE asks two questions of every file: who holds the copyright, and under what licence is it published. A file can answer in three ways.</p><ol><li><p><strong>An SPDX header</strong> in the file itself.</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// SPDX-FileCopyrightText: 2026 Your Name</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">//</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// SPDX-License-Identifier: MIT OR Apache-2.0</span></span></code></pre></div></li><li><p><strong>A <code>.license</code> companion</strong> beside it, for files that cannot carry a comment -- a PNG, a binary fixture. <code>logo.png</code> is answered by <code>logo.png.license</code>.</p></li><li><p><strong>An annotation in <code>REUSE.toml</code></strong>, which covers many files at once. This is how most projects license their documentation and configuration without putting a header in every file.</p></li></ol><p>Every licence a project uses must also exist as a text file in <code>LICENSES/</code>.</p><h2 id="first-run" tabindex="-1">First run <a class="header-anchor" href="#first-run" aria-label="Permalink to “First run”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>REUSE lint report</span></span>
<span class="line"><span>113 total, 112 passed, 0 failed, 1 skipped</span></span></code></pre></div><p>The exit status carries the verdict -- <code>0</code> when compliant -- so it works as a CI gate directly:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quiet</span></span></code></pre></div><p>If files are missing information, <code>--lines</code> prints one finding per line, which is the format editors and CI annotations understand:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lines</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>src/main.rs: missing copyright</span></span>
<span class="line"><span>src/main.rs: missing license</span></span></code></pre></div><h2 id="making-a-project-compliant" tabindex="-1">Making a project compliant <a class="header-anchor" href="#making-a-project-compliant" aria-label="Permalink to “Making a project compliant”">​</a></h2><p>Start from nothing:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --license</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MIT OR Apache-2.0&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --holder</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name &lt;you@example.com&gt;&quot;</span></span></code></pre></div><p>That writes a <code>REUSE.toml</code> and creates <code>LICENSES/</code>. Then fetch the licence texts the project references but does not yet have:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p>Then add headers. For specific files:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> annotate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --license</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --copyright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;2026 Your Name&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/main.rs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/lib.rs</span></span></code></pre></div><p>Or repair everything the configuration can already answer for:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # show what would change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">             # apply it</span></span></code></pre></div><p><code>fix</code> only writes where it has an answer. A file with no header and no matching annotation is reported, not guessed at.</p><h2 id="in-pre-commit" tabindex="-1">In pre-commit <a class="header-anchor" href="#in-pre-commit" aria-label="Permalink to “In pre-commit”">​</a></h2><p>Checking the whole project on every commit means walking every file to judge a handful. <code>lint-file</code> scales with the change instead:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/main.rs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/lib.rs</span></span></code></pre></div><p>Wire it into a hook so it receives the staged files. Keep a full <code>comply lint</code> in CI, because the project-wide findings -- unused licences, missing licence texts -- are the ones <code>lint-file</code> cannot make.</p><h2 id="producing-a-bill-of-materials" tabindex="-1">Producing a bill of materials <a class="header-anchor" href="#producing-a-bill-of-materials" aria-label="Permalink to “Producing a bill of materials”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spdx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> comply.spdx</span></span></code></pre></div><p>An SPDX 2.1 tag-value document listing every checked file with its licence and checksums. The document namespace is derived from the file set rather than randomly generated, so an unchanged tree produces a byte-identical document and two runs can be diffed in review.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/comply/docs/guide/configuration">Configuration</a> -- <code>REUSE.toml</code> and the <code>[tool.comply]</code> extensions.</li><li><a href="/comply/docs/reference/cli">CLI reference</a> -- every command and flag.</li><li><a href="/comply/PARITY">Parity report</a> -- how comply compares against <code>reuse</code> 6.2.0.</li></ul>`,39)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};